update public.paid_content as content
set payload = jsonb_set(
      jsonb_set(
        jsonb_set(
          content.payload,
          '{title}',
          to_jsonb(life_updates.title)
        ),
        '{essence}',
        to_jsonb(life_updates.essence)
      ),
      '{subtitle}',
      to_jsonb(life_updates.essence)
    ) || case
      when life_updates.explanation is null then '{}'::jsonb
      else jsonb_build_object('explanation', life_updates.explanation)
    end,
    updated_at = now()
from life_updates
where content.content_type = 'technique'
  and content.content_id = life_updates.content_id;
